        const data = await res.json();
        throw new Error(data.error || 'Error al añadir candidato');
      }
      setSuccess('Candidato añadido exitosamente.');
      setForm({ firstName: '', lastName: '', email: '', phone: '', address: '', education: '', workExperience: '' });
      setCv(null);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} style={{ maxWidth: 500, margin: '2rem auto', padding: 24, border: '1px solid #ccc', borderRadius: 8 }}>
      <h2>Añadir Candidato</h2>
      <div>
        <label>Nombre*:<br />
          <input name="firstName" value={form.firstName} onChange={handleChange} required />
        </label>
      </div>
      <div>
        <label>Apellido*:<br />
          <input name="lastName" value={form.lastName} onChange={handleChange} required />
        </label>
      </div>
      <div>
        <label>Email*:<br />
          <input name="email" type="email" value={form.email} onChange={handleChange} required />
        </label>
      </div>
      <div>
        <label>Teléfono:<br />
          <input name="phone" value={form.phone} onChange={handleChange} />
        </label>
      </div>
      <div>
        <label>Dirección:<br />
          <input name="address" value={form.address} onChange={handleChange} />
        </label>
      </div>
      <div>
        <label>Educación:<br />
          <input name="education" value={form.education} onChange={handleChange} />
        </label>
      </div>
      <div>
        <label>Experiencia Laboral:<br />
          <textarea name="workExperience" value={form.workExperience} onChange={handleChange} />
        </label>
      </div>
      <div>
        <label>CV (PDF o DOCX, máx. 5MB):<br />
          <input name="cv" type="file" accept=".pdf,.doc,.docx,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document" onChange={handleFileChange} />
        </label>
      </div>
      {error && <div style={{ color: 'red', marginTop: 8 }}>{error}</div>}
      {success && <div style={{ color: 'green', marginTop: 8 }}>{success}</div>}
      <button type="submit" disabled={loading} style={{ marginTop: 16 }}>
        {loading ? 'Enviando...' : 'Añadir Candidato'}
      </button>
    </form>
  );
};

export default AddCandidateForm;
