export class CandidateService {
  constructor(private readonly candidateRepository: ICandidateRepository) {}

  async createCandidate(candidateData: {
    firstName: string;
    lastName: string;
    email: string;
    phone?: string;
    address?: string;
    education?: string;
    workExperience?: string;
    cvUrl?: string;
  }): Promise<Candidate> {
    const existingCandidate = await this.candidateRepository.findByEmail(candidateData.email);
    if (existingCandidate) {
      throw new Error('Candidate with this email already exists');
    }

    const candidate = new Candidate(
      null,
      candidateData.firstName,
      candidateData.lastName,
      candidateData.email,
      candidateData.phone,
      candidateData.address,
      candidateData.education,
      candidateData.workExperience,
      candidateData.cvUrl
    );

    return this.candidateRepository.create(candidate);
  }

  async getAllCandidates(): Promise<Candidate[]> {
    return this.candidateRepository.findAll();
  }

  async getCandidateById(id: number): Promise<Candidate> {
    const candidate = await this.candidateRepository.findById(id);
    if (!candidate) {
      throw new Error('Candidate not found');
    }
    return candidate;
  }
