import Header from '../layout/Header';

interface CandidateListProps {
  onMenuToggle: () => void;
}

interface Candidate {
  id: number;
  firstName: string;
  lastName: string;
  email: string;
  phone?: string;
  education?: string;
  cvUrl?: string;
}

const CandidateList: React.FC<CandidateListProps> = ({ onMenuToggle }) => {
  const [candidates, setCandidates] = useState<Candidate[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchCandidates();
  }, []);

  const fetchCandidates = async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await fetch('http://localhost:3010/candidates');
      if (!response.ok) {
        throw new Error('Error loading candidates');
      }
      const data = await response.json();
      setCandidates(data);
    } catch (error) {
      setError(
        error instanceof Error
          ? error.message
          : 'An error occurred while loading candidates'
      );
      console.error('Error:', error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="text-center p-5">
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Loading...</span>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="alert alert-danger" role="alert">
        {error}
      </div>
    );
  }

  return (
    <div className="container-fluid px-4">
      <Header
        title="Candidates"
        subtitle={`${candidates.length} ${candidates.length === 1 ? 'candidate' : 'candidates'} registered`}
        onMenuToggle={onMenuToggle}
      />

      <div className="card shadow-sm">
        <div className="card-body">
          {candidates.length === 0 ? (
            <div className="text-center p-5">
              <p className="text-muted mb-0">
                No candidates registered yet.
              </p>
            </div>
          ) : (
            // ...existing code...
          )}
        </div>
      </div>
    </div>
  );
};

export default CandidateList;"}

